"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78522"],{45449(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.opcoes_de_curso_invalido","status":422,"titulo":"O n\xfamero de op\xe7\xf5es de curso deve ser 1 ou 2"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.opcoes_de_curso_invalido","requisitos":["UNI-REQ-0024"],"oQueAconteceu":["O n\xfamero de op\xe7\xf5es de curso informado para o processo seletivo n\xe3o \xe9 1 nem 2.\\nUma inscri\xe7\xe3o pode registrar uma s\xf3 op\xe7\xe3o de curso ou, quando o processo\\npermite, uma segunda; n\xe3o h\xe1 processo com zero op\xe7\xf5es nem com mais de duas\\n(UNI-REQ-0024)."],"comoResolver":["Informe `1` ou `2` como n\xfamero de op\xe7\xf5es de curso e envie de novo. Com `2`,\\na distribui\xe7\xe3o de vagas do processo precisa ter ao menos duas ofertas\\n(cursos diferentes ou o mesmo curso em outro campus ou turno); do contr\xe1rio a resposta ser\xe1\\n[`opcoes_de_curso_acima_das_ofertas`](/erros/uniplus.selecao.processo_seletivo.opcoes_de_curso_acima_das_ofertas).\\nCom `1`, este pedido n\xe3o exige mais nada."],"ondeAparece":["Defini\xe7\xe3o do n\xfamero de op\xe7\xf5es de curso do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);